  ?point ref:hasTimeseriesId ?tsid .
  ?point a ?class .
  ?point ref:hasExternalReference ?ref .
} LIMIT 200

SELECT ?zone ?label WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?label }
}

SELECT ?zone ?label ?room WHERE {
  ?zone rdfs:label ?label .
  ?zone brick:hasPart ?room .
  FILTER(?label LIKE '%Core_mid%')
}

SELECT ?room ?sensor ?tsid WHERE {
  ?zone rdfs:label ?label .
  FILTER(?label = 'Core_mid')
  ?zone brick:hasPart ?room .
  ?room brick:hasPoint ?sensor .
  ?sensor a brick:Air_Temperature_Sensor ;
          ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tsid .
}

